lert'=>'Ҳушдор','block descriptionA notice for your visitors: information, success, a warning or an error, with an optional title and a close button.'=>'Огоҳии пешниҳодшуда барои меҳмонон: маълумот, муваффақият, огоҳӣ ё хатогӣ, бо унвони ихтиёрӣ ва тугмаи пӯшидан.','block keywordnotice'=>'огоҳинома','block keywordmessage'=>'паём','block keywordcallout'=>'огоҳинома','block keywordwarning'=>'огоҳӣ','block titleButton link'=>'Истиноди тугма','block descriptionA link styled as a button.'=>'Як истиноди ҳамчун тугма тарроҳишуда.','block keywordbutton'=>'тугма','block keywordlink'=>'пайванд','block keywordcall to action'=>'даъват ба амал','block titleColumn'=>'Сутун','block descriptionA column inside a row. It can hold any block.'=>'Сутун дар дохили сатр. Он метавонад ҳама гуна блокҳоро дар бар гирад.','block keywordcolumn'=>'сутун','block keywordlayout'=>'тарҳбандӣ','block titleContainer'=>'Контейнер','block descriptionA box that lays out the blocks inside it with flexbox or a grid. Nest containers to build any layout. Stays readable if the plugin is ever turned off.'=>'Як қуттие, ки блокҳои даруни худро бо flexbox ё сетка ҷойгир мекунад. Контейнерҳоро барои сохтани ягон макет дар ҳамдигар ҷойгир кунед. Агар плагин ягон бор хомӯш карда шавад ҳам, хондашаванда боқӣ мемонад.','block keywordcontainer'=>'контейнер','block keywordbox'=>'қуттӣ','block keywordgrid'=>'шабакаи торӣ','block keywordflexbox'=>'флексбокс','block keywordcolumns'=>'сутунҳо','block titleLanguage switcher (sample)'=>'Ивазкунандаи забоon (намуна)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Забоonҳои сайтиро аз плагини тарҷума, ҳангоми фаъол будани он, номбар мекунад. Дар акси ҳол ҳеҷ чизро нишон намедиҳад.','block keywordlanguage'=>'Забон','block keywordswitcher'=>'ивазкунанда','block titleSample content'=>'Муҳтавои намунавӣ','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Сарлавҳа ва параграф, ки бо номҳои синфи бетараф тасвир шудаанд. Ин блоки истинодӣ барои шартномаи тарҷума аст.','block keywordsample'=>'намуна','block keywordtext'=>'матн','block titleIcon'=>'Нишона','block descriptionAn SVG icon. The markup is cleaned before it is shown.'=>'Нишонаи SVG. Пеш аз нишон додан, рамзҳо тоза карда мешаванд.','block keywordicon'=>'нишонҷот','block keywordsvg'=>'SVG','block titleLanguage switcher'=>'Ивагаркунандаи забон','block descriptionLets visitors read this page in another language, styled to match your page. Needs the Tranzly plugin for the languages.'=>'Ба меҳмонон имкон медиҳад, ки ин саҳифаро бо забони дигар, ки мувофиқи саҳифаи шумо ороиш ёфтааст, хонанд. Барои забонҳо плагини Tranzly лозим аст.','block keywordtranslation'=>'тарҷума','block keywordmultilingual'=>'серҷавоба','block titleDark mode switch'=>'Гузариш ба ҳолати торик','block descriptionA button that switches the website between its light and dark colours, and remembers the visitor\'s choice.'=>'Тугмае, ки вебсайтбро байти рангҳои рӯшноӣ ва торики он иваз мекунад ва интихоби боздидкунандаро ба ёд нигоҳ медорад.','block keyworddark'=>'Торик','block keywordlight'=>'равшан','block keywordcolour scheme'=>'нақши рангҳо','block titleRow'=>'Сатр','block descriptionA row of columns. Stays readable if the plugin is ever turned off.'=>'Қatorи сутунҳо. Агар плагин хомӯш карда шавад ҳам, хондашаванда боқӣ мемонад.','block keywordrow'=>'сатр','block titleSection'=>'Қисм','block descriptionA full-width band of the page that lays its content out with flexbox or a grid. Stays readable if the plugin is ever turned off.'=>'Як банд бо паҳнои пурраи саҳифа, ки мундариҷаи худро бо истифода аз flexbox ё grid ҷойгир мекунад. Ҳангоми хомӯш будани плагин низ хоно боқӣ мемонад.','block keywordsection'=>'фасл','block titleShortcode (add-on)'=>'Рамзи кӯтоҳ (илова)','block descriptionA shortcode from an add-on written for the classic Page Builder Sandwich editor, with the settings the add-on declared.'=>'Як ширкод аз иловае, ки барои муҳаррири классикии Page Builder Sandwich навишта шудааст, бо танзимоте, ки илова эълон кардааст.','block keywordshortcode'=>'коди кӯтоҳ','block keywordadd-on'=>'иловагӣ','block titleWidget area'=>'Ноҳияи виджетҳо','block descriptionShows the widgets in one of the theme\'s widget areas.'=>'Виҷетҳоро дар яке аз минтақаҳои виҷети мавзӯъ нишон медиҳад.','block keywordsidebar'=>'лавҳаи канорӣ','block keywordwidget area'=>'минтақаи виҷетҳо','block titleWidget'=>'Виҷет','block descriptionShows one of the site\'s registered classic widgets.'=>'Яке аз виджетҳои классикии сабтиномшудаи сайтҳоро нишон медиҳад.','block keywordwidget'=>'виҷет']];